import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, BehaviorSubject } from 'rxjs';
import { tap } from 'rxjs/operators';

interface User {
  id: number;
  name: string;
  email: string;
}

interface AuthResponse {
  user: User;
  token: string;
}

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  private apiUrl = 'http://localhost:3000/api'; // Rails APIのURL
  private currentUserSubject = new BehaviorSubject<User | null>(null);
  public currentUser$ = this.currentUserSubject.asObservable();

  constructor(private http: HttpClient) {
    // ローカルストレージからユーザー情報を復元
    const savedUser = localStorage.getItem('currentUser');
    if (savedUser) {
      this.currentUserSubject.next(JSON.parse(savedUser));
    }
  }

  // 新規登録
  register(userData: {
    fullname: string;
    email: string;
    password: string;
    passwordConfirm: string;
  }): Observable<AuthResponse> {
    return this.http
      .post<AuthResponse>(`${this.apiUrl}/v2/users`, {
        user: {
          fullname: userData.fullname,
          email_address: userData.email,
          password: userData.password,
          password_confirmation: userData.passwordConfirm,
        },
      })
      .pipe(
        tap((response) => {
          // トークンとユーザー情報を保存
          localStorage.setItem('authToken', response.token);
          localStorage.setItem('currentUser', JSON.stringify(response.user));
          this.currentUserSubject.next(response.user);
        }),
      );
  }

  // ログイン
  login(credentials: {
    email: string;
    password: string;
  }): Observable<AuthResponse> {
    return this.http
      .post<AuthResponse>(`${this.apiUrl}/auth/login`, {
        user: {
          email: credentials.email,
          password: credentials.password,
        },
      })
      .pipe(
        tap((response) => {
          // トークンとユーザー情報を保存
          localStorage.setItem('authToken', response.token);
          localStorage.setItem('currentUser', JSON.stringify(response.user));
          this.currentUserSubject.next(response.user);
        }),
      );
  }

  // ログアウト
  logout(): Observable<any> {
    return this.http.delete(`${this.apiUrl}/auth/logout`).pipe(
      tap(() => {
        // ローカルストレージをクリア
        localStorage.removeItem('authToken');
        localStorage.removeItem('currentUser');
        this.currentUserSubject.next(null);
      }),
    );
  }

  // 現在のユーザーを取得
  getCurrentUser(): User | null {
    return this.currentUserSubject.value;
  }

  // トークンを取得
  getToken(): string | null {
    return localStorage.getItem('authToken');
  }

  // ログイン状態を確認
  isLoggedIn(): boolean {
    return !!this.getToken();
  }
}

import { Component } from '@angular/core';
import { AddButtonComponent } from '@/components/add-button/add-button.component';
import { EditModalBaseComponent } from '@/components/edit-modal-base/edit-modal-base.component';
import { CardBaseComponent } from '@/components/card-base/card-base.component';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { CategoryTabsComponent } from '@/components/category-tabs/category-tabs.component';

interface FavoriteItem {
  brandName: string;
  itemName: string;
  url: string;
  price: number | null;
  memo: string;
  category?: string;
}

@Component({
  selector: 'app-favorites',
  imports: [
    AddButtonComponent,
    EditModalBaseComponent,
    CardBaseComponent,
    FormsModule,
    CommonModule,
    CategoryTabsComponent,
  ],
  templateUrl: './favorites.component.html',
  styleUrl: './favorites.component.css',
})
export class FavoritesComponent {
  // モーダル管理
  isModalOpen = false;

  // カテゴリー
  readonly CATEGORIES = [
    'すべて',
    'ファッション',
    'メイク',
    'アクセサリー',
    'カラコン',
    'その他',
  ];

  // 選択中のカテゴリー
  selectedCategory = 'すべて';

  // 新規アイテム
  newItem = this.getEmptyItem() as FavoriteItem;

  // お気に入りリスト（後でRails APIから取得）
  favorites: any[] = [];

  // ブランド名の選択肢（後でRails APIから取得）
  existingBrandNames: string[] = [];

  // 現在のカテゴリーを取得
  get currentCategory(): string {
    return this.selectedCategory;
  }

  // フィルタリングされたお気に入り
  get filteredFavorites(): any[] {
    if (this.selectedCategory === 'すべて') {
      return this.favorites;
    }
    return this.favorites.filter(item => item.category === this.selectedCategory);
  }

  // 子コンポーネント(タブ)からの通知を受け取る関数
  onCategoryChanged(category: string) {
    this.selectedCategory = category;
  }

  // モーダルのカテゴリーオプション
  get modalCategoryOptions() {
    return this.CATEGORIES.filter((c) => c !== 'すべて');
  }

  // 空のアイテムを作成
  private getEmptyItem(): FavoriteItem {
    return {
      brandName: '',
      itemName: '',
      url: '',
      price: null,
      memo: '',
      category: 'ファッション',
    };
  }

  // モーダルを開く
  openAddModal() {
    this.newItem = this.getEmptyItem();
    this.isModalOpen = true;
  }

  // モーダルを閉じる
  handleClose() {
    this.isModalOpen = false;
  }

  // 保存処理（後でRails APIと連携）
  async saveItem() {
    if (!this.newItem.brandName.trim() || !this.newItem.itemName.trim()) {
      alert('ブランド名と商品名は必須です');
      return;
    }

    // TODO: Rails APIにPOSTリクエストを送信
    console.log('アイテム保存:', this.newItem);

    // 仮のローカル追加
    this.favorites.unshift({
      id: Date.now(),
      ...this.newItem,
      createdAt: new Date(),
    });

    this.isModalOpen = false;
    this.newItem = this.getEmptyItem();
  }
}

