import { CategoryTabsComponent } from '@/components/category-tabs/category-tabs.component';

@Component({
  selector: 'app-brands',
  imports: [
    FormsModule,
    AddButtonComponent,
    EditModalBaseComponent,
    CommonModule,
    CategoryTabsComponent,
  ],
  templateUrl: './brands.component.html',
  styleUrl: './brands.component.css',
})
