    this.isModalOpen = false;
  }

  // モーダルのカテゴリーオプション
  get modalCategoryOptions() {
    return this.CATEGORIES.filter((c) => c !== 'すべて');
  }

  // 保存処理（後でRails APIと連携）
  async saveBrand() {
    if (this.newBrand.name.trim()) {
      // TODO: Rails APIにPOSTリクエストを送信
      console.log('ブランド保存:', this.newBrand);

      // 仮のローカル追加
      this.brands.unshift({
        id: Date.now(),
        ...this.newBrand,
        createdAt: new Date(),
      });

      this.isModalOpen = false;
      this.newBrand = {
        name: '',
        category: 'ファッション',
        description: '',
        url: '',
